import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

export type ToastType = "info" | "success" | "error" | "warning";

export interface ToastOptions {
  type?: ToastType;
  durationMs?: number;
}

interface ToastEntry {
  id: number;
  message: string;
  type: ToastType;
  durationMs: number;
  /** time remaining when the countdown was paused (hover) */
  remainingMs: number;
  /** timestamp of when the countdown last (re)started, or null while paused */
  resumedAt: number | null;
}

export const MAX_VISIBLE_TOASTS = 3;
const DEFAULT_DURATION_MS = 5000;

interface ToastContextValue {
  push: (message: string, options?: ToastOptions) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) {
    throw new Error("useToast must be used within a <ToastProvider>");
  }
  return ctx;
}

let nextToastId = 1;

function now() {
  return Date.now();
}

export function ToastProvider({ children }: { children: React.ReactNode }) {
  // All toasts that have been pushed and not yet dismissed/expired.
  const [toasts, setToasts] = useState<ToastEntry[]>([]);
  const timers = useRef<Map<number, ReturnType<typeof setTimeout>>>(new Map());

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((t) => clearTimeout(t));
      pending.clear();
    };
  }, []);

  const scheduleDismiss = useCallback((entry: ToastEntry) => {
    if (entry.resumedAt === null) return; // paused
    const existing = timers.current.get(entry.id);
    if (existing !== undefined) clearTimeout(existing);
    const handle = setTimeout(() => {
      timers.current.delete(entry.id);
      setToasts((prev) =>
        prev.filter((t) => t.id !== entry.id).map((t) => ({ ...t })),
      );
    }, entry.remainingMs);
    timers.current.set(entry.id, handle);
  }, []);

  const push = useCallback(
    (message: string, options: ToastOptions = {}) => {
      const entry: ToastEntry = {
        id: nextToastId++,
        message,
        type: options.type ?? "info",
        durationMs: options.durationMs ?? DEFAULT_DURATION_MS,
        remainingMs: options.durationMs ?? DEFAULT_DURATION_MS,
        resumedAt: now(),
      };
      setToasts((prev) => [...prev, entry]);
      // Only the newest MAX_VISIBLE_TOASTS count down; queued ones start
      // their timer once they become visible.
      setToasts((prev) => {
        const visible = prev.slice(-MAX_VISIBLE_TOASTS);
        visible.forEach(scheduleDismiss);
        return [...prev];
      });
    },
    [scheduleDismiss],
  );

  const dismiss = useCallback((id: number) => {
    const t = timers.current.get(id);
    if (t !== undefined) {
      clearTimeout(t);
      timers.current.delete(id);
    }
    setToasts((prev) => prev.filter((entry) => entry.id !== id));
  }, []);

  const pause = useCallback((id: number) => {
    setToasts((prev) =>
      prev.map((entry) => {
        if (entry.id !== id || entry.resumedAt === null) return entry;
        const elapsed = now() - entry.resumedAt;
        const remaining = Math.max(0, entry.remainingMs - elapsed);
        const t = timers.current.get(id);
        if (t !== undefined) {
          clearTimeout(t);
          timers.current.delete(id);
        }
        return { ...entry, remainingMs: remaining, resumedAt: null };
      }),
    );
  }, []);

  const resume = useCallback(
    (id: number) => {
      setToasts((prev) => {
        const updated = prev.map((entry) => {
          if (entry.id !== id || entry.resumedAt !== null) return entry;
          return { ...entry, resumedAt: now() };
        });
        const entry = updated.find((t) => t.id === id);
        if (entry) scheduleDismiss(entry);
        return updated;
      });
    },
    [scheduleDismiss],
  );

  const visibleToasts = useMemo(
    () => toasts.slice(-MAX_VISIBLE_TOASTS),
    [toasts],
  );
  const queuedCount = Math.max(0, toasts.length - MAX_VISIBLE_TOASTS);

  const value = useMemo(() => ({ push }), [push]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div className="toast-region">
        {/* Screen readers announce new toasts politely; the region itself is
            not a status/alert so its label stays quiet. */}
        <div role="region" aria-label="Notifications" aria-live="polite">
          {visibleToasts.map(({ id, message, type }) => (
            <div
              key={id}
              data-testid="toast"
              data-toast-id={id}
              className={`toast toast--${type}`}
              onMouseOver={() => pause(id)}
              onMouseOut={() => resume(id)}
            >
              <span>{message}</span>
              <button
                type="button"
                aria-label={`Dismiss notification: ${message}`}
                onClick={() => dismiss(id)}
              >
                ×
              </button>
            </div>
          ))}
        </div>
      </div>
    </ToastContext.Provider>
  );
}

