import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

export type ToastType = "info" | "success" | "error" | "warning";

export interface ToastOptions {
  type?: ToastType;
  durationMs?: number;
}

interface ToastEntry {
  id: number;
  message: string;
  type: ToastType;
  /** total display duration once fully visible */
  durationMs: number;
  /** time left on the countdown */
  remainingMs: number;
  /** timestamp the countdown last (re)started, or null while paused/queued */
  resumedAt: number | null;
}

export const MAX_VISIBLE_TOASTS = 3;
const DEFAULT_DURATION_MS = 5000;

export interface ToastContextValue {
  push: (message: string, options?: ToastOptions) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) {
    throw new Error("useToast must be used within a <ToastProvider>");
  }
  return ctx;
}

let nextToastId = 1;

function currentTime(): number {
  return Date.now();
}

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<ToastEntry[]>([]);
  const timers = useRef<Map<number, ReturnType<typeof setTimeout>>>(
    new Map(),
  );

  const expire = useCallback((id: number) => {
    timers.current.delete(id);
    setToasts((prev) => prev.filter((entry) => entry.id !== id));
  }, []);

  // Keep timers in sync with state: exactly the newest MAX_VISIBLE_TOASTS
  // unpaused toasts have a live countdown. Queued toasts do not start
  // counting down until they become visible.
  useEffect(() => {
    const visibleIds = new Set(
      toasts.slice(-MAX_VISIBLE_TOASTS).map((t) => t.id),
    );

    for (const [id, handle] of timers.current) {
      const entry = toasts.find((t) => t.id === id);
      const needsTimer =
        entry !== undefined &&
        visibleIds.has(id) &&
        entry.resumedAt !== null;
      if (!needsTimer) {
        clearTimeout(handle);
        timers.current.delete(id);
      }
    }

    for (const entry of toasts) {
      if (!visibleIds.has(entry.id) || entry.resumedAt === null) continue;
      if (timers.current.has(entry.id)) continue;
      const id = entry.id;
      timers.current.set(
        id,
        setTimeout(() => expire(id), entry.remainingMs),
      );
    }
  }, [toasts, expire]);

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((handle) => clearTimeout(handle));
      pending.clear();
    };
  }, []);

  const push = useCallback((message: string, options: ToastOptions = {}) => {
    const durationMs = options.durationMs ?? DEFAULT_DURATION_MS;
    setToasts((prev) => [
      ...prev,
      {
        id: nextToastId++,
        message,
        type: options.type ?? "info",
        durationMs,
        remainingMs: durationMs,
        // Queued toasts stay paused until they reach the visible stack.
        resumedAt: prev.length < MAX_VISIBLE_TOASTS ? currentTime() : null,
      },
    ]);
  }, []);

  const dismiss = useCallback((id: number) => {
    setToasts((prev) => prev.filter((entry) => entry.id !== id));
  }, []);

  const pause = useCallback((id: number) => {
    setToasts((prev) =>
      prev.map((entry) => {
        if (entry.id !== id || entry.resumedAt === null) return entry;
        const elapsed = currentTime() - entry.resumedAt;
        const handle = timers.current.get(id);
        if (handle !== undefined) {
          clearTimeout(handle);
          timers.current.delete(id);
        }
        return {
          ...entry,
          remainingMs: Math.max(0, entry.remainingMs - elapsed),
          resumedAt: null,
        };
      }),
    );
  }, []);

  const resume = useCallback((id: number) => {
    setToasts((prev) =>
      prev.map((entry) =>
        entry.id === id && entry.resumedAt === null
          ? { ...entry, resumedAt: currentTime() }
          : entry,
      ),
    );
  }, []);

  const visibleToasts = useMemo(
    () => toasts.slice(-MAX_VISIBLE_TOASTS),
    [toasts],
  );

  const value = useMemo(() => ({ push }), [push]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div className="toast-region">
        <div role="region" aria-label="Notifications">
          <div aria-live="polite" aria-atomic="false">
            {visibleToasts.map(({ id, message, type }) => (
              <div
                key={id}
                data-testid="toast"
                data-toast-id={id}
                data-toast-type={type}
                className={`toast toast--${type}`}
                onMouseOver={() => pause(id)}
                onMouseOut={() => resume(id)}
              >
                <span className="toast__message">{message}</span>
                <button
                  type="button"
                  aria-label={`Dismiss notification: ${message}`}
                  onClick={() => dismiss(id)}
                >
                  Dismiss
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </ToastContext.Provider>
  );
}

