import React from "react";
import { render, screen, fireEvent, act } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  ToastProvider,
  useToast,
  MAX_VISIBLE_TOASTS,
} from "./ToastProvider";

const DURATION = 3000;

function Harness({
  durationMs = DURATION,
}: {
  durationMs?: number;
}) {
  const { push } = useToast();
  return (
    <div>
      <button onClick={() => push(`toast-${pushCount}`, { durationMs })}>
        push
      </button>
      <span hidden>{(pushCount += 0)}</span>
    </div>
  );
}

let pushCount = 1;

function getToasts(): HTMLElement[] {
  return screen.queryAllByTestId("toast");
}

function pushToast() {
  fireEvent.click(screen.getByText("push"));
}

beforeEach(() => {
  vi.useFakeTimers();
  pushCount = 1;
});

afterEach(() => {
  act(() => {
    vi.runOnlyPendingTimers();
  });
  vi.useRealTimers();
});

describe("ToastProvider", () => {
  it("auto-dismisses each toast after its duration", () => {
    render(
      <ToastProvider>
        <Harness />
      </ToastProvider>,
    );
    pushToast();
    expect(getToasts()).toHaveLength(1);

    act(() => {
      vi.advanceTimersByTime(DURATION - 1);
    });
    expect(getToasts()).toHaveLength(1);

    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(getToasts()).toHaveLength(0);
  });

  it("supports per-toast durationMs", () => {
    render(
      <ToastProvider>
        <Harness durationMs={100} />
      </ToastProvider>,
    );
    pushToast();
    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(getToasts()).toHaveLength(0);
  });

  it("queues the fourth toast until one of the visible three expires", () => {
    render(
      <ToastProvider>
        <Harness />
      </ToastProvider>,
    );

    for (let i = 0; i < 4; i++) {
      pushToast();
    }

    // Max of 3 visible, newest-last ordering.
    const visible = getToasts();
    expect(visible).toHaveLength(MAX_VISIBLE_TOASTS);
    expect(visible[visible.length - 1]).toHaveTextContent("toast-4");
    expect(visible[0]).toHaveTextContent("toast-1");

    // The queued fourth toast must not count down while queued: even after
    // a full duration passes, only the oldest visible one has expired.
    act(() => {
      vi.advanceTimersByTime(DURATION);
    });
    let now = getToasts();
    expect(now.map((t) => t.textContent)).toEqual([
      "toast-2",
      "toast-3",
      "toast-4",
    ]);

    // The promoted fourth toast now counts down its own full duration.
    act(() => {
      vi.advanceTimersByTime(DURATION - 1);
    });
    expect(getToasts()).toHaveLength(MAX_VISIBLE_TOASTS);
    act(() => {
      vi.advanceTimersByTime(1);
    });
    now = getToasts();
    expect(now.map((t) => t.textContent)).toEqual([
      "toast-3",
      "toast-4",
    ]);
  });

  it("pauses the countdown while hovered and resumes on mouse out", () => {
    render(
      <ToastProvider>
        <Harness />
      </ToastProvider>,
    );
    pushToast();
    const toast = getToasts()[0];

    // Hover partway through, then wait well past the remaining time.
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    fireEvent.mouseOver(toast);

    act(() => {
      vi.advanceTimersByTime(DURATION * 10);
    });
    // Still present: countdown was paused.
    expect(getToasts()).toHaveLength(1);

    // Resume on mouse out; only the remaining ~2000ms are needed.
    fireEvent.mouseOut(toast);
    act(() => {
      vi.advanceTimersByTime(DURATION - 1000 - 1);
    });
    expect(getToasts()).toHaveLength(1);

    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(getToasts()).toHaveLength(0);
  });

  it("dismisses a toast via its labelled dismiss button", () => {
    render(
      <ToastProvider>
        <Harness />
      </ToastProvider>,
    );
    pushToast();

    const button = screen.getByRole("button", {
      name: "Dismiss notification: toast-1",
    });
    fireEvent.click(button);
    expect(getToasts()).toHaveLength(0);

    // Manual dismissal does not leave stray timers firing later.
    act(() => {
      vi.advanceTimersByTime(DURATION * 5);
    });
    expect(getToasts()).toHaveLength(0);
  });

  it("renders toasts inside an aria-live polite region", () => {
    render(
      <ToastProvider>
        <div>child</div>
      </ToastProvider>,
    );
    const region = screen.getByRole("region", { name: "Notifications" });
    expect(region).toBeInTheDocument();
    const live = region.querySelector("[aria-live='polite']");
    expect(live).not.toBeNull();
  });
});

