import React from "react";
import { render, screen, fireEvent, act } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  ToastProvider,
  useToast,
  MAX_VISIBLE_TOASTS,
} from "./ToastProvider";

const DURATION = 3000;

/** Test harness exposing a button that pushes sequentially-named toasts. */
function makeHarness(
  optionsFor?: (n: number) => { type?: string; durationMs?: number },
) {
  let count = 0;
  return function Harness() {
    const { push } = useToast();
    return (
      <button
        onClick={() => {
          count++;
          push(`toast-${count}`, optionsFor?.(count));
        }}
      >
        push
      </button>
    );
  };
}

function pushToast() {
  fireEvent.click(screen.getByText("push"));
}

/** Messages of currently rendered (visible) toasts, oldest-first. */
function visibleMessages(): string[] {
  return screen.queryAllByTestId("toast").map(
    (t) =>
      (t.querySelector(".toast__message") as HTMLElement).textContent ?? "",
  );
}

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  act(() => {
    vi.runOnlyPendingTimers();
  });
  vi.useRealTimers();
});

describe("ToastProvider", () => {
  it("auto-dismisses each toast after its duration", () => {
    render(
      <ToastProvider>
        <makeHarness />
      </ToastProvider>,
    );
    pushToast();
    expect(visibleMessages()).toEqual(["toast-1"]);

    act(() => {
      vi.advanceTimersByTime(DURATION - 1);
    });
    expect(visibleMessages()).toEqual(["toast-1"]);

    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(visibleMessages()).toEqual([]);
  });

  it("honours a custom durationMs", () => {
    render(
      <ToastProvider>
        <makeHarness={(n) => ({ durationMs: n * 100 })} />
      </ToastProvider>,
    );
    pushToast();
    pushToast();

    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(visibleMessages()).toEqual(["toast-2"]);

    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(visibleMessages()).toEqual([]);
  });

  it("queues the fourth toast and admits it only once one expires", () => {
    render(
      <ToastProvider>
        {/* First toast has a shorter life so we can observe a single expiry. */}
        <makeHarness={(n) => ({ durationMs: n === 1 ? 1000 : DURATION })}
        />
      </ToastProvider>,
    );
    for (let i = 0; i < 4; i++) pushToast();

    // Max 3 visible, newest-last within the stack.
    expect(visibleMessages()).toEqual(["toast-1", "toast-2", "toast-3"]);
    expect(screen.getAllByTestId("toast")).toHaveLength(MAX_VISIBLE_TOASTS);

    // The queued toast must not count down while queued: just before the
    // first expiry everything is still on screen.
    act(() => {
      vi.advanceTimersByTime(999);
    });
    expect(visibleMessages()).toEqual(["toast-1", "toast-2", "toast-3"]);

    // Oldest expires -> the queued fourth toast is admitted (newest-last).
    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(visibleMessages()).toEqual(["toast-2", "toast-3", "toast-4"]);

    // The promoted fourth toast runs its own full duration from admission.
    act(() => {
      vi.advanceTimersByTime(DURATION - 1);
    });
    expect(visibleMessages()).toEqual(["toast-2", "toast-3", "toast-4"]);

    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(visibleMessages()).toEqual(["toast-3", "toast-4"]);

    act(() => {
      vi.advanceTimersByTime(DURATION);
    });
    expect(visibleMessages()).toEqual([]);
  });

  it("pauses the countdown while hovered and resumes on mouse out", () => {
    render(
      <ToastProvider>
        <makeHarness />
      </ToastProvider>,
    );
    pushToast();
    const toast = screen.getByTestId("toast");

    // Hover partway through the countdown...
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    fireEvent.mouseOver(toast);

    // ...then wait far beyond the original duration.
    act(() => {
      vi.advanceTimersByTime(DURATION * 10);
    });
    expect(visibleMessages()).toEqual(["toast-1"]);

    // On mouse out only the paused remainder (~2000ms) is left.
    fireEvent.mouseOut(toast);
    act(() => {
      vi.advanceTimersByTime(DURATION - 1000 - 1);
    });
    expect(visibleMessages()).toEqual(["toast-1"]);

    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(visibleMessages()).toEqual([]);
  });

  it("dismisses manually via the labelled dismiss button", () => {
    render(
      <ToastProvider>
        <makeHarness />
      </ToastProvider>,
    );
    pushToast();
    pushToast();

    const button = screen.getByRole("button", {
      name: "Dismiss notification: toast-1",
    });
    fireEvent.click(button);
    expect(visibleMessages()).toEqual(["toast-2"]);

    // Manual dismissal leaves no stray timer behind.
    act(() => {
      vi.advanceTimersByTime(DURATION * 5);
    });
    expect(visibleMessages()).toEqual([]);
  });

  it("renders inside an aria-live polite notifications region", () => {
    render(
      <ToastProvider>
        <div>child content</div>
      </ToastProvider>,
    );

    // Children stay rendered alongside the provider's portal-like region.
    expect(screen.getByText("child content")).toBeInTheDocument();

    const liveRegion = document.querySelector("[aria-live='polite']");
    expect(liveRegion).not.toBeNull();
    expect(
      liveRegion!.closest('[role="region"][aria-label="Notifications"]'),
    ).not.toBeNull();
  });
});

